ALTER TABLE public.claim_rows
  ADD COLUMN IF NOT EXISTS recommendation text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS rule text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS policy_version text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS explanation text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS missing_fields text NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS request_status text;
ALTER TABLE public.claim_rows ADD CONSTRAINT claim_rows_request_status_check CHECK (request_status IS NULL OR request_status IN ('requested','answered_awaiting_recheck'));
ON CONFLICT (case_id) DO UPDATE SET case_status = EXCLUDED.case_status, claim_summary = EXCLUDED.claim_summary, policy_active_on_incident = EXCLUDED.policy_active_on_incident, claim_type = EXCLUDED.claim_type, repair_type = EXCLUDED.repair_type, quote_eur = EXCLUDED.quote_eur, incident_report_present = EXCLUDED.incident_report_present, itemized_quote_present = EXCLUDED.itemized_quote_present, injury_reported = EXCLUDED.injury_reported, liability_disputed = EXCLUDED.liability_disputed, duplicate_flag = EXCLUDED.duplicate_flag, evidence_conflict = EXCLUDED.evidence_conflict, recommendation = EXCLUDED.recommendation, rule = EXCLUDED.rule, policy_version = EXCLUDED.policy_version, explanation = EXCLUDED.explanation, missing_fields = EXCLUDED.missing_fields, updated_at = now();